param([int]$Trials = 5)
Add-Type @"
using System; using System.Runtime.InteropServices;
public static class Shl {
  [DllImport("shell32.dll", CharSet=CharSet.Unicode)] static extern int SHParseDisplayName(string name, IntPtr bc, out IntPtr pidl, uint sfgaoIn, out uint sfgaoOut);
  [DllImport("shell32.dll")] static extern int SHOpenFolderAndSelectItems(IntPtr pidlFolder, uint cidl, IntPtr apidl, uint flags);
  [DllImport("ole32.dll")] static extern void CoTaskMemFree(IntPtr p);
  public static int Reveal(string path) {
    IntPtr pidl; uint o; int hr = SHParseDisplayName(path, IntPtr.Zero, out pidl, 0, out o);
    if (hr != 0) return hr;
    try { return SHOpenFolderAndSelectItems(pidl, 0, IntPtr.Zero, 0); } finally { CoTaskMemFree(pidl); }
  }
}
"@
$dir = Join-Path $env:TEMP 'klippy-reveal-test'
New-Item -ItemType Directory -Force $dir | Out-Null
1..5 | % { Set-Content (Join-Path $dir "file$_.md") 'x' }
$target = Join-Path $dir 'file3.md'
$sh = New-Object -ComObject Shell.Application

function Views { @($sh.Windows()) | ? { try { $_.Document.Folder.Self.Path -eq $dir } catch { $false } } }
function CloseAll { Views | % { $_.Quit() }; Start-Sleep -Milliseconds 1500 }
function ClearSel { foreach ($v in Views) { foreach ($i in @($v.Document.SelectedItems())) { $v.Document.SelectItem($i, 0) } } }
function Result {
  Start-Sleep -Milliseconds 3000
  $v = @(Views)
  $sel = ($v | % { ($_.Document.SelectedItems() | % Name) -join ',' }) -join ' / '
  "views=$($v.Count) selected=[$sel]"
}
function Explorer { $psi = New-Object Diagnostics.ProcessStartInfo 'explorer.exe'; $psi.UseShellExecute = $false
  $psi.ArgumentList.Add('/select,'); $psi.ArgumentList.Add($target); [Diagnostics.Process]::Start($psi) | Out-Null }
function Api { $hr = [Shl]::Reveal($target); if ($hr) { "hr=0x{0:X}" -f $hr } }

foreach ($m in 'Explorer','Api') {
  "== $m, folder not open =="
  1..$Trials | % { CloseAll; & $m; "  $_ " + (Result) }
  "== $m, folder already open, nothing selected =="
  1..$Trials | % { ClearSel; & $m; "  $_ " + (Result) }
}
CloseAll
