using System;
using System.Runtime.InteropServices;
using System.Runtime.Versioning;
using System.Threading;

namespace Klippy.Services;

/// <summary>
/// Shows a file selected in Explorer by asking the shell directly, rather than by starting
/// <c>explorer.exe /select,</c>.
///
/// The shell selects the file in a window already showing its folder, where
/// <c>/select,</c> opens another window each time. And a new window is what tab utilities
/// such as ExplorerTabUtility catch and fold into a tab, losing the selection on the way —
/// every time, when that folder is already open in a tab.
/// </summary>
[SupportedOSPlatform("windows")]
internal static class ShellReveal
{
    /// <summary>
    /// Whether the shell took the path. False is no message for the user: the caller falls
    /// back to <c>explorer.exe</c>, which answers a path it cannot show in its own way.
    /// </summary>
    public static bool TrySelect(string path)
    {
        // The shell wants COM, and a single-threaded apartment of its own is the one it is
        // happiest in — not the pool thread a run arrives on, whose apartment is not ours
        // to choose.
        var selected = false;
        var thread = new Thread(() => selected = Select(path)) { IsBackground = true };
        thread.SetApartmentState(ApartmentState.STA);
        thread.Start();
        thread.Join();
        return selected;
    }

    private static bool Select(string path)
    {
        if (CoInitializeEx(IntPtr.Zero, COINIT_APARTMENTTHREADED) < 0) return false;
        try
        {
            if (SHParseDisplayName(path, IntPtr.Zero, out var item, 0, out _) < 0) return false;
            try
            {
                // No children named: the item itself is selected in the folder it is in.
                return SHOpenFolderAndSelectItems(item, 0, IntPtr.Zero, 0) >= 0;
            }
            finally
            {
                CoTaskMemFree(item);
            }
        }
        finally
        {
            CoUninitialize();
        }
    }

    private const uint COINIT_APARTMENTTHREADED = 0x2;

    [DllImport("ole32.dll")]
    private static extern int CoInitializeEx(IntPtr reserved, uint coInit);

    [DllImport("ole32.dll")]
    private static extern void CoUninitialize();

    [DllImport("ole32.dll")]
    private static extern void CoTaskMemFree(IntPtr pv);

    [DllImport("shell32.dll", CharSet = CharSet.Unicode)]
    private static extern int SHParseDisplayName(string name, IntPtr bindingContext, out IntPtr pidl,
        uint attributesIn, out uint attributesOut);

    [DllImport("shell32.dll")]
    private static extern int SHOpenFolderAndSelectItems(IntPtr folder, uint count, IntPtr items, uint flags);
}

